 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.setdefault(color, []).append(cells)

    def shape(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    target_shapes = {shape(cells) for cells in components.get(8, [])}
    out = [row[:] for row in grid]
    for color, comps in components.items():
        if color == 8:
            continue
        for cells in comps:
            if shape(cells) in target_shapes:
                for r, c in cells:
                    out[r][c] = 8
    return out
